BEGIN READ ONLY; SELECT jsonb_agg(jsonb_build_object('kind','dependency','identity',v.identity,'fingerprint',md5(v.identity||':'||v.multiplicity))) AS catalog FROM (SELECT to_jsonb(x)::text identity,count(*)::text multiplicity FROM (SELECT d.deptype,(pg_identify_object(d.classid,d.objid,d.objsubid)).type AS object_type,(pg_identify_object(d.classid,d.objid,d.objsubid)).schema AS object_schema,(pg_identify_object(d.classid,d.objid,d.objsubid)).identity AS object_identity,(pg_identify_object(d.refclassid,d.refobjid,d.refobjsubid)).type AS referenced_type,(pg_identify_object(d.refclassid,d.refobjid,d.refobjsubid)).schema AS referenced_schema,(pg_identify_object(d.refclassid,d.refobjid,d.refobjsubid)).identity AS referenced_identity FROM pg_depend d WHERE d.deptype <> 'p' AND ((pg_identify_object(d.classid,d.objid,d.objsubid)).schema IN ('public','private','credentialing') OR d.deptype='e')) x GROUP BY to_jsonb(x)::text) v; COMMIT;
